package com.glassbox.chess; import com.glassbox.chess.ai.*; import com.glassbox.chess.domain.*; import com.glassbox.chess.rule.MoveValidator; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; public class AITest{@Test void minimaxReturnsLegalMove(){Board b=new Board();b.setupInitialPosition();Move m=new MinimaxAI(2,2000).calculateMove(b,()->false);assertNotNull(m);assertTrue(MoveValidator.getLegalMoves(b,Color.WHITE).stream().anyMatch(x->x.getFrom().equals(m.getFrom())&&x.getTo().equals(m.getTo())));}}
